config.script:
import 'java.util.UUID' as UUID;
import 'java.util.Date' as Date;
import 'java.security.MessageDigest' as MessageDigest;
import 'java.lang.System' as System;
import 'java.lang.Integer' as Integer;

var row = input.rows[0];
// 报文数据：SQL 列去掉 send_flag 和回写键；日期转字符串；追加追溯码节点（与 PB 一致保留原字段）
var data = {};
for (key, val in row) {
    if (key != 'send_flag' && key != 'pk_value') {
        data[key] = val instanceof Date ? date_format(val, 'yyyy-MM-dd HH:mm:ss') : val;
    }
}
if (row.drug_trac_codg != null && row.drug_trac_codg != '') {
    data.drugtracinfo = [{drug_trac_codg: row.drug_trac_codg}];
}
// x-tif-signature = sha256(timestamp + secret + nonce + timestamp)
var stamp = '' + (System.currentTimeMillis() / 1000);
var nonce = UUID.randomUUID().toString();
var bytes = MessageDigest.getInstance('SHA-256').digest((stamp + '${var.gdyb.secretkey}' + nonce + stamp).getBytes('UTF-8'));
var signature = '';
for (b in bytes) {
    var h = Integer.toHexString(b & 0xFF);
    signature = signature + (h.length() == 1 ? '0' + h : h);
}
var r4 = '000' + (System.nanoTime() % 10000);
var msgid = '${var.gdyb.fixmedins-code}' + date_format(now(), 'yyyyMMddHHmmss') + r4.substring(r4.length() - 4);
return {row: row, data: data, timestamp: stamp, nonce: nonce, signature: signature, msgid: msgid};
